const SOLAR_EXAM_BANK = [
  // ===== Solar Fundamentals (10) =====
  { id: 'sol-001', category: 'Solar Fundamentals', question: 'What does kW measure in a solar system?', choices: ['Energy used or produced over time', 'The square footage of the roof', 'The monthly utility bill amount', 'The size or power capacity of the system'], answerIndex: 3, explain: 'kW is \'the size of the engine\' — it measures the system\'s power capacity, while kWh measures energy over time.' },
  { id: 'sol-002', category: 'Solar Fundamentals', question: 'What does kWh measure?', choices: ['The system size or capacity', 'Energy used or produced over a period of time', 'The roof tilt angle', 'The inverter brand efficiency rating'], answerIndex: 1, explain: 'kWh is what the utility actually bills for — the amount of energy used or produced over time.' },
  { id: 'sol-003', category: 'Solar Fundamentals', question: 'What does \'offset\' mean in residential solar?', choices: ['The percent of usage covered by solar production', 'A discount applied to financing rates', 'The amount of shading on a roof', 'A rebate issued by the inverter manufacturer'], answerIndex: 0, explain: '100% offset means the system’s annual production roughly matches the home’s annual usage.' },
  { id: 'sol-004', category: 'Solar Fundamentals', question: 'What is the correct order of energy flow in a residential solar system?', choices: ['Inverter converts AC to DC, then panels store it', 'Grid electricity charges the panels overnight', 'Panels produce DC electricity, the inverter converts it to AC, the home uses it, and excess can export to the grid', 'The electrical panel produces DC power directly'], answerIndex: 2, explain: 'Panels generate DC power, the inverter makes it usable AC power, the home uses it first, and only extra generation exports to the grid.' },
  { id: 'sol-005', category: 'Solar Fundamentals', question: 'How does the manual describe net metering?', choices: ['Credits for eligible exported energy, where the grid acts like an accounting system rather than a physical battery', 'A type of battery installed in the home', 'A financing product offered by the utility', 'A federal tax credit program'], answerIndex: 0, explain: 'Net metering provides bill credits for eligible exported power; the grid functions as an accounting mechanism, not literal energy storage.' },
  { id: 'sol-006', category: 'Solar Fundamentals', question: 'What must happen before a system can receive Permission to Operate (PTO)?', choices: ['The roof must be repainted', 'Utility interconnection approval', 'A battery must be added to the design', 'The homeowner must switch electricity suppliers'], answerIndex: 1, explain: 'Interconnection approval from the utility is required before a system is granted PTO and allowed to operate.' },
  { id: 'sol-007', category: 'Solar Fundamentals', question: 'Which statement correctly distinguishes production from consumption?', choices: ['Production is home electricity usage; consumption is solar output', 'Production only applies to battery systems', 'They are two names for the same measurement', 'Production is how much energy the system generates; consumption is how much energy the home uses'], answerIndex: 3, explain: 'Production depends on system size, sun, orientation, and shading; consumption is shown on the bill and 12-month usage history.' },
  { id: 'sol-008', category: 'Solar Fundamentals', question: 'Why does the manual highlight Massachusetts\' electricity rates as part of the sales opportunity?', choices: ['MA has among the lowest electric rates in the country', 'Electric rates in MA have never changed', 'MA homeowners pay some of the highest electric rates in the US, and average prices have risen significantly over decades', 'Solar is not currently permitted in Massachusetts'], answerIndex: 2, explain: 'MA has some of the highest residential electric rates in the country, and average prices have risen substantially, making bill control and predictability valuable to homeowners.' },
  { id: 'sol-009', category: 'Solar Fundamentals', question: 'What is the accurate statement about resilience for a solar-only system with no battery?', choices: ['Outage protection is guaranteed regardless of system design', 'Solar alone always powers the home during an outage', 'Every solar system automatically includes battery backup', 'Solar alone typically shuts off during a grid outage for safety reasons'], answerIndex: 3, explain: 'Solar-only systems normally shut off during an outage for safety; only a properly designed battery-backed system can power selected circuits.' },
  { id: 'sol-010', category: 'Solar Fundamentals', question: 'Which of these reflects the manual\'s \'do not overpromise\' guidance?', choices: ['Don\'t guarantee a $0 bill, quote unverified incentives, promise backup without a battery, or give tax advice', 'Quote incentive dollar amounts without verifying them for the specific project', 'Always guarantee a $0 monthly bill', 'Give the customer specific tax advice directly'], answerIndex: 0, explain: 'Reps must avoid guaranteeing a $0 bill, quoting unverified incentives, promising outage backup without a battery, and giving tax advice — refer tax questions to a professional.' },

  // ===== System Components (9) =====
  { id: 'sol-011', category: 'System Components', question: 'What is the role of the racking/mounting system?', choices: ['Converts DC electricity to AC', 'Secures panels to the roof', 'Tracks energy sent to and from the grid', 'Stores excess solar energy'], answerIndex: 1, explain: 'Racking and mounting hardware physically secures the panels to the roof structure.' },
  { id: 'sol-012', category: 'System Components', question: 'Which component converts DC electricity from the panels into usable AC electricity?', choices: ['The inverter', 'The net meter', 'The electrical panel', 'The racking system'], answerIndex: 0, explain: 'The inverter converts the panels’ DC output into AC power the home’s circuits and appliances can use.' },
  { id: 'sol-013', category: 'System Components', question: 'What role does the home\'s electrical panel play in a solar system?', choices: ['It captures sunlight to generate electricity', 'It stores backup power for outages', 'It records exported energy for utility credits', 'It distributes solar power through household circuits and connects the system to home wiring'], answerIndex: 3, explain: 'The electrical panel distributes solar power through the home and ties the solar system into household circuits.' },
  { id: 'sol-014', category: 'System Components', question: 'What does the utility meter / net meter do?', choices: ['Tracks energy sent to and received from the grid', 'Converts AC power to DC power', 'Physically mounts panels to the roof', 'Provides backup power during outages'], answerIndex: 0, explain: 'A bi-directional utility/net meter tracks energy flowing both ways, which is how the utility determines export credits.' },
  { id: 'sol-015', category: 'System Components', question: 'Which optional component stores extra solar energy for nighttime use or outages?', choices: ['Racking system', 'Battery storage', 'Inverter', 'Monitoring system'], answerIndex: 1, explain: 'Battery storage is optional and stores excess solar energy for later use, including during outages if the system is designed for backup.' },
  { id: 'sol-016', category: 'System Components', question: 'What benefit does a monitoring system give a homeowner?', choices: ['Guaranteed backup power during an outage', 'Extended panel warranty coverage', 'A lower fixed customer charge', 'The ability to track solar production and system performance'], answerIndex: 3, explain: 'Monitoring systems let homeowners see how much the system is producing and how well it is performing over time.' },
  { id: 'sol-017', category: 'System Components', question: 'Which two general inverter configurations are common in residential solar (industry-standard)?', choices: ['AC panels and DC net meters', 'String inverters and microinverters', 'Battery inverters and racking inverters', 'Roof inverters and grid inverters'], answerIndex: 1, explain: 'Residential systems typically use either a central string inverter or panel-level microinverters, each with different design tradeoffs.' },
  { id: 'sol-018', category: 'System Components', question: 'What does the grid connection provide to a solar-equipped home?', choices: ['Only export capability, never any backup', 'Direct DC power to household appliances', 'Structural support for the racking system', 'Backup power access when needed, and a path for excess solar energy to be exported'], answerIndex: 3, explain: 'The grid connection can supply backup power to the home and also receives excess solar energy the home exports.' },
  { id: 'sol-019', category: 'System Components', question: 'Which component would a rep point to when explaining how exported solar credits get tracked on a customer\'s bill?', choices: ['The racking system', 'The bi-directional utility/net meter', 'The inverter cooling fan', 'The roof flashing'], answerIndex: 1, explain: 'The bi-directional meter records energy flow in both directions, which is what allows the utility to issue export credits.' },

  // ===== Site Qualification (9) =====
  { id: 'sol-020', category: 'Site Qualification', question: 'Which roof orientation generally produces the best solar output?', choices: ['North-facing', 'East-facing only', 'Any direction produces identical output', 'South, southeast, or southwest-facing'], answerIndex: 3, explain: 'South, southeast, and southwest-facing roofs typically capture the most usable sunlight for production.' },
  { id: 'sol-021', category: 'Site Qualification', question: 'Why does roof condition matter for site qualification?', choices: ['It affects the homeowner\'s credit score', 'Roof condition has no effect on qualification', 'A roof in good condition with years of remaining life is ideal before panels are installed', 'Only shingle color matters for qualification'], answerIndex: 2, explain: 'Installing on a roof nearing the end of its life creates rework and added cost, so good condition with remaining life is ideal.' },
  { id: 'sol-022', category: 'Site Qualification', question: 'Which qualification factor evaluates trees, chimneys, or nearby buildings blocking sunlight?', choices: ['Structural integrity', 'Electrical panel capacity', 'Ownership and utility access', 'Shade exposure'], answerIndex: 3, explain: 'Shade exposure looks at obstructions like trees, chimneys, or nearby buildings that can reduce production.' },
  { id: 'sol-023', category: 'Site Qualification', question: 'Why must the home\'s electrical panel be reviewed during qualification?', choices: ['To confirm it has adequate capacity or is eligible for an upgrade', 'To measure the roof tilt angle', 'To calculate expected shading loss', 'To determine which utility company serves the home'], answerIndex: 0, explain: 'The panel must have adequate capacity, or be upgradable, for the solar system to safely interconnect.' },
  { id: 'sol-024', category: 'Site Qualification', question: 'Which homes often benefit most from going solar, per the site qualification guidance?', choices: ['Homes with very low electricity usage', 'Homes with higher electricity usage', 'Vacant homes', 'Homes with no roof access at all'], answerIndex: 1, explain: 'Homes with higher usage typically have more bill exposure for solar production to offset, making them stronger candidates.' },
  { id: 'sol-025', category: 'Site Qualification', question: 'What must be true about ownership and utility access for a strong solar candidate?', choices: ['The customer should be renting, not owning', 'The home must be completely off-grid', 'The homeowner should own the property and have utility service suitable for interconnection', 'The home must already have battery storage installed'], answerIndex: 2, explain: 'Ownership lets the customer authorize the project, and suitable utility service is required for proper interconnection.' },
  { id: 'sol-026', category: 'Site Qualification', question: 'Which factor evaluates whether the roof structure can safely hold the panel system?', choices: ['Structural integrity', 'Available roof space', 'Roof orientation and tilt', 'Energy usage'], answerIndex: 0, explain: 'Structural integrity confirms the roof can safely support the added weight and mounting hardware of a solar system.' },
  { id: 'sol-027', category: 'Site Qualification', question: 'What does \'available roof space\' assess during qualification?', choices: ['The age of the home\'s electrical panel', 'The roof\'s paint or shingle color', 'Whether there is enough open, unobstructed area for the needed number of panels', 'The utility\'s rate class'], answerIndex: 2, explain: 'Sufficient open, unobstructed roof space is needed to fit the number of panels the design requires.' },
  { id: 'sol-028', category: 'Site Qualification', question: 'How many key site qualification factors does the manual outline for a good solar home?', choices: ['5', '6', '10', '8'], answerIndex: 3, explain: 'The manual lists 8 factors: orientation/tilt, roof condition, shade, roof space, structural integrity, electrical panel, energy usage, and ownership/utility access.' },

  // ===== Utility Bills (10) =====
  { id: 'sol-029', category: 'Utility Bills', question: 'How many structural parts does a typical Massachusetts electric bill have, per the manual?', choices: ['2', '4', '3', '6'], answerIndex: 1, explain: 'MA bills generally break into supply charges, delivery charges, customer/fixed charges, and taxes/adjustments/riders.' },
  { id: 'sol-030', category: 'Utility Bills', question: 'What can solar typically reduce on a utility bill?', choices: ['The fixed customer/account charge', 'The utility\'s overall infrastructure costs', 'State sales tax line items', 'The kWh of electricity supply the customer needs to purchase'], answerIndex: 3, explain: 'Solar production offsets usage, reducing the amount of supply the customer needs to buy from the utility or a supplier.' },
  { id: 'sol-031', category: 'Utility Bills', question: 'Why might a \'$0 utility bill\' not be realistic even with solar?', choices: ['Solar panels degrade completely after one year of use', 'A monthly fixed or customer charge often remains regardless of solar production', 'Net metering is not legal in Massachusetts', 'Inverters cannot handle full offset systems'], answerIndex: 1, explain: 'A fixed monthly customer/account charge often continues even when a home produces solar, so a true $0 bill is not always realistic.' },
  { id: 'sol-032', category: 'Utility Bills', question: 'What is the rep rule about how much usage history to collect from a customer?', choices: ['A single recent bill is always sufficient', 'Only summer usage needs to be reviewed', 'Usage history isn\'t needed once the roof qualifies', '12 months of usage history should be gathered because usage varies seasonally in Massachusetts'], answerIndex: 3, explain: 'A one-month bill is not enough to size a system correctly, since MA usage changes meaningfully across seasons.' },
  { id: 'sol-033', category: 'Utility Bills', question: 'What do delivery charges on a MA electric bill generally cover?', choices: ['The cost to deliver power through poles, wires, substations, customer service, and related programs', 'The cost of generating the electricity itself', 'Federal solar tax credits', 'Panel manufacturer warranty costs'], answerIndex: 0, explain: 'Delivery charges cover getting power to the home — poles, wires, substations, customer service, and public benefit/grid programs.' },
  { id: 'sol-034', category: 'Utility Bills', question: 'On a National Grid bill, what does the \'Distributed Solar Charge\' line item generally help fund?', choices: ['Federal income tax credits', 'The customer\'s own solar system cost', 'EV charging stations exclusively', 'Local solar programs and infrastructure'], answerIndex: 3, explain: 'The Distributed Solar Charge helps support local solar programs and infrastructure on National Grid bills.' },
  { id: 'sol-035', category: 'Utility Bills', question: 'On an Eversource bill, what does the \'Generation Srvc Chrg\' represent?', choices: ['The cost charged by the supplier for generating or supplying the power', 'The fixed monthly account charge', 'A renewable energy credit line item', 'A late payment penalty'], answerIndex: 0, explain: 'Generation Service Charge is the supply-side charge for the electricity itself, listed under supply charges.' },
  { id: 'sol-036', category: 'Utility Bills', question: 'Where should a rep point a customer to find their annual electricity consumption on a National Grid bill?', choices: ['The payment due date box', 'The customer\'s credit score section', 'The electric usage history chart showing kWh by month', 'The inverter warranty page'], answerIndex: 2, explain: 'The usage history chart on the bill shows kWh by month, which reps use to estimate annual consumption.' },
  { id: 'sol-037', category: 'Utility Bills', question: 'What does the Customer Charge generally represent on a utility bill?', choices: ['A one-time solar installation fee', 'A renewable energy incentive payment', 'The cost of net metering credits earned', 'A fixed charge for basic service that stays roughly the same regardless of usage'], answerIndex: 3, explain: 'The Customer/Customer Chrg is a fixed charge for basic service, largely independent of how much electricity is used.' },
  { id: 'sol-038', category: 'Utility Bills', question: 'Why must reps read a bill line by line rather than guess at charges?', choices: ['Because delivery charges never appear on residential bills', 'Because every MA bill is formatted identically', 'Because taxes, adjustments, and rider line items vary and should never be assumed', 'Because supply charges are always listed at zero'], answerIndex: 2, explain: 'Taxes, adjustments, and riders vary by customer, utility, and billing period, so reps must read the actual bill instead of assuming.' },

  // ===== Net Metering (9) =====
  { id: 'sol-039', category: 'Net Metering', question: 'What is the first step in the net metering process described in the manual?', choices: ['The utility mails a credit statement', 'A bi-directional meter is newly installed', 'The home draws power from the grid at night', 'Solar panels produce electricity during the day'], answerIndex: 3, explain: 'The process starts with panels producing electricity during the day; the home uses that power first before any export happens.' },
  { id: 'sol-040', category: 'Net Metering', question: 'What happens to bill credits generated from exported solar energy?', choices: ['They expire immediately and cannot be used', 'They can only be transferred to a neighbor', 'They reduce what the customer pays when drawing power from the grid during low-production times', 'They automatically convert into a cash rebate check'], answerIndex: 2, explain: 'Bill credits from exported energy reduce what the customer owes when they later draw power from the grid, such as at night.' },
  { id: 'sol-041', category: 'Net Metering', question: 'Which phrase from the manual best summarizes net metering\'s value to a homeowner?', choices: ['\'Save today. Use tomorrow. That\'s the power of Net Metering.\'', '\'Sign now or lose everything\'', '\'The government pays for it\'', '\'You will never pay an electric bill again\''], answerIndex: 0, explain: 'This is the manual\'s summary line explaining how net metering banks daytime production as a credit usable later.' },
  { id: 'sol-042', category: 'Net Metering', question: 'What role does the bi-directional meter play in net metering?', choices: ['It converts DC electricity to AC', 'It stores battery backup power on-site', 'It measures extra electricity sent to the grid and enables the utility to track exports for credits', 'It sets the customer\'s supply rate'], answerIndex: 2, explain: 'The bi-directional meter is how extra electricity sent to the grid is measured, enabling accurate export credit tracking.' },
  { id: 'sol-043', category: 'Net Metering', question: 'Is the grid best described as a physical battery under net metering?', choices: ['No, it functions like an accounting system rather than a physical battery', 'Yes, it stores the exact electrons for the customer to retrieve later', 'Yes, but only within Eversource territory', 'No, because net metering does not exist in Massachusetts'], answerIndex: 0, explain: 'The manual is explicit that net metering credits function like an accounting system, not literal energy storage.' },
  { id: 'sol-044', category: 'Net Metering', question: 'What must happen before a net-metered system is eligible to begin earning export credits?', choices: ['A battery must be installed', 'The customer must switch electricity suppliers', 'The utility must grant interconnection approval and Permission to Operate', 'The roof must be fully replaced'], answerIndex: 2, explain: 'Interconnection approval and PTO from the utility are required before a system can legally operate and begin generating exportable credits.' },
  { id: 'sol-045', category: 'Net Metering', question: 'When does a solar home typically draw electricity from the grid despite having solar panels?', choices: ['At night or during low production times', 'Only during scheduled maintenance visits', 'Net metering means the home never draws from the grid', 'Only during the winter months'], answerIndex: 0, explain: 'At night or in low-production periods the home draws from the grid, and any available bill credits reduce that cost.' },
  { id: 'sol-046', category: 'Net Metering', question: 'What determines net metering credit values for a given customer, per the manual?', choices: ['The customer\'s personal credit score', 'The brand of inverter installed', 'The applicable utility and tariff rules', 'The color of the solar panels'], answerIndex: 2, explain: 'Net metering rules and credit values depend on the utility and the tariff that applies to the specific customer account.' },
  { id: 'sol-047', category: 'Net Metering', question: 'Which best explains interconnection in the solar process?', choices: ['Physically connecting two solar panels together', 'The utility approval process required before a system can receive Permission to Operate', 'A type of solar financing agreement', 'A method for calculating roof shading loss'], answerIndex: 1, explain: 'Interconnection is the utility approval process that must be completed before a system is authorized to operate.' },

  // ===== Financing (9) =====
  { id: 'sol-048', category: 'Financing', question: 'Which financing option typically offers the highest long-term return with no monthly finance payment?', choices: ['PPA', 'Lease', 'Cash purchase', 'Solar loan'], answerIndex: 2, explain: 'A cash purchase has no financing payment and gives full ownership, generally producing the highest long-term return.' },
  { id: 'sol-049', category: 'Financing', question: 'What best describes a Power Purchase Agreement (PPA)?', choices: ['The customer owns the system outright with no payments', 'The utility owns and operates the system at no cost to the customer', 'The customer pays a flat monthly rate regardless of production', 'The customer pays for the solar energy the system produces at a contract price, usually without owning the system'], answerIndex: 3, explain: 'In a PPA, the customer typically does not own the system and instead pays per kWh produced at an agreed contract price.' },
  { id: 'sol-050', category: 'Financing', question: 'What best describes a solar lease?', choices: ['Ownership secured through a loan payment', 'A fixed monthly payment for access to the system, usually without ownership', 'A one-time upfront cash payment for the system', 'A pay-per-kWh production agreement'], answerIndex: 1, explain: 'A lease provides low upfront cost with a fixed monthly payment for system access; the customer usually does not own it.' },
  { id: 'sol-051', category: 'Financing', question: 'What best describes a solar loan?', choices: ['The customer never owns the system under any circumstances', 'The utility bills the loan with no customer involvement', 'The customer finances and owns the system, with the loan payment typically replacing much of the previous utility spend', 'It requires no credit or income review'], answerIndex: 2, explain: 'A solar loan finances ownership with low or no upfront cost, with the payment typically replacing much of prior utility spend.' },
  { id: 'sol-052', category: 'Financing', question: 'What should a rep ask before recommending a specific financing option?', choices: ['How many rooms are in your house?', 'Nothing — always default to a solar loan', 'What brand of car do you drive?', 'Is your priority lowest monthly payment, ownership, backup power, or long-term return?'], answerIndex: 3, explain: 'The rep rule is to diagnose the customer’s priority before proposing financing, not to sell financing before understanding their goals.' },
  { id: 'sol-053', category: 'Financing', question: 'What kind of value can a battery add-on typically provide?', choices: ['Guaranteed whole-home backup regardless of system design', 'An automatic $0 utility bill', 'Backup for properly designed circuits and potential demand-response program value', 'A free roof replacement'], answerIndex: 2, explain: 'Batteries can support backup for circuits the system is designed for and may qualify for demand-response programs, but scope depends on design.' },
  { id: 'sol-054', category: 'Financing', question: 'What should a rep understand about the federal Residential Clean Energy Credit, per IRS guidance referenced in the manual?', choices: ['It is permanent and never expires', 'It is issued automatically with no tax filing required', 'It only applies to battery storage, never to panels', 'It applies to qualified property installed 2022 through December 31, 2025, and is not available for property placed in service after that date'], answerIndex: 3, explain: 'Per the IRS OBBB termination FAQ referenced in the manual, the 30% credit applies through December 31, 2025, and is unavailable after that date.' },
  { id: 'sol-055', category: 'Financing', question: 'Why must reps verify SMART program details rather than quoting a fixed figure to every customer?', choices: ['SMART is not an actual Massachusetts program', 'SMART payment structure and eligibility depend on program rules and application status, which can vary', 'SMART only applies to battery installations', 'SMART guarantees an identical payout for every applicant'], answerIndex: 1, explain: 'SMART eligibility and payment structure depend on program rules and application status, so reps should not overquote specific figures without verification.' },
  { id: 'sol-056', category: 'Financing', question: 'What must every rep do regarding tax benefits and incentives when presenting numbers to a customer?', choices: ['Confidently state exact dollar amounts from memory', 'Avoid mentioning incentives at all', 'Guarantee the incentive will apply to every customer', 'Disclose that incentives and tax benefits may change, and refer tax-specific questions to a tax professional'], answerIndex: 3, explain: 'The manual requires disclosing that incentives and tax benefits may change, and directing tax questions to a qualified tax professional.' },

  // ===== Savings (9) =====
  { id: 'sol-057', category: 'Savings', question: 'What are the main components of the manual\'s solar savings formula?', choices: ['Roof size, panel color, and inverter brand', 'Current utility cost, solar payment, remaining utility bill, incentives/credits, and net monthly value', 'Credit score, down payment, and loan term', 'Sunlight hours, wind speed, and outdoor temperature'], answerIndex: 1, explain: 'The formula walks from current utility cost through the solar payment and remaining bill to incentives, arriving at net monthly value.' },
  { id: 'sol-058', category: 'Savings', question: 'Which inputs must a rep gather before proposing a system, per the manual\'s \'must-have inputs\'?', choices: ['Only the customer\'s name and mailing address', 'Only the customer\'s credit score', 'Only the roof\'s square footage', '12-month kWh usage, current utility rate, supplier status, roof design, production estimate, financing option, incentive eligibility, and customer goals'], answerIndex: 3, explain: 'A proper proposal requires usage history, rate and supplier info, roof and production data, financing choice, incentive eligibility, and customer goals.' },
  { id: 'sol-059', category: 'Savings', question: 'What disclosure must accompany every solar production estimate presented to a customer?', choices: ['That production estimates are guaranteed, exact figures', 'That production estimates are not guarantees', 'That production estimates apply only to battery systems', 'That production estimates never need to be shown to the customer'], answerIndex: 1, explain: 'The manual explicitly requires disclosing that solar production estimates are projections, not guarantees.' },
  { id: 'sol-060', category: 'Savings', question: 'What typically remains part of the \'remaining utility bill\' even after solar is installed?', choices: ['Nothing — the bill always reaches $0', 'Only the customer\'s third-party supplier fee', 'Fixed/customer charges plus any usage not covered by solar production', 'Only state tax line items'], answerIndex: 2, explain: 'The remaining bill typically includes fixed/customer charges and any usage beyond what solar production offsets.' },
  { id: 'sol-061', category: 'Savings', question: 'What must a rep tell a customer about incentives and tax benefits when discussing savings?', choices: ['They may change, and the customer should get tax professional guidance', 'They are guaranteed and permanent for every customer', 'They apply automatically with no eligibility check needed', 'They only matter if a battery is included'], answerIndex: 0, explain: 'Required disclosures include that incentives and tax benefits may change and that customers should seek tax professional guidance.' },
  { id: 'sol-062', category: 'Savings', question: 'What does \'net monthly value\' represent in the savings formula?', choices: ['Only the loan payment amount', 'The overall savings, stability, and resilience value after accounting for the solar payment, remaining bill, and incentives', 'The utility\'s total company revenue', 'The panel manufacturer\'s warranty terms'], answerIndex: 1, explain: 'Net monthly value is the end result of the formula, reflecting overall savings, predictability, and resilience benefit to the customer.' },
  { id: 'sol-063', category: 'Savings', question: 'Which of these is a required disclosure before a customer signs, regarding the overall process?', choices: ['The customer should review the proposal, utility approval process, and financing agreement', 'The customer does not need to read the financing agreement', 'Financing terms are identical across every provider', 'Financing approval is guaranteed for every applicant'], answerIndex: 0, explain: 'Customers should review the proposal, the utility approval process, and financing agreement details, in addition to seeking tax guidance.' },
  { id: 'sol-064', category: 'Savings', question: 'Which customer input should shape which financing/savings option a rep recommends?', choices: ['The rep\'s personal commission preference alone', 'Whichever option closes fastest, regardless of fit', 'Always the cheapest possible option, regardless of stated goals', 'The customer\'s stated priority (lowest payment, ownership, backup, or long-term return)'], answerIndex: 3, explain: 'The rep should diagnose the customer\'s actual priority first, then align the savings and financing conversation to that goal.' },
  { id: 'sol-065', category: 'Savings', question: 'Why should a rep avoid promising an exact savings percentage without caveats?', choices: ['Because savings and production are estimates based on assumptions like usage, weather, rate structure, and system design', 'Because savings never actually occur with solar', 'Because savings claims only apply to commercial customers', 'Because Massachusetts prohibits discussing savings at all'], answerIndex: 0, explain: 'Production and savings are estimates, not guarantees, since they depend on variable assumptions such as usage and weather.' },

  // ===== Discovery (9) =====
  { id: 'sol-066', category: 'Discovery', question: 'Which discovery question targets \'bill pain\'?', choices: ['Do you own the home?', 'Do you have a garage?', 'What\'s your favorite season?', 'What bothers you most about your electric bill?'], answerIndex: 3, explain: 'This question directly surfaces the customer\'s frustration with their bill, a core discovery category.' },
  { id: 'sol-067', category: 'Discovery', question: 'Which discovery question addresses \'future usage\'?', choices: ['How old is your roof?', 'Are you adding EVs, mini-splits, heat pumps, a pool, or more living space?', 'Who is the decision maker on this?', 'What time do you usually leave for work?'], answerIndex: 1, explain: 'This question explores upcoming changes that could increase electricity usage, informing future system sizing.' },
  { id: 'sol-068', category: 'Discovery', question: 'Which question falls under the \'decision process\' discovery category?', choices: ['Any leaks or shade issues on the roof?', 'Are you open to cash, loan, or PPA/lease?', 'Besides you, who else should review the numbers?', 'Do outages matter to you?'], answerIndex: 2, explain: 'This identifies other decision-makers who should be included in the review, part of the decision-process discovery category.' },
  { id: 'sol-069', category: 'Discovery', question: 'Which discovery question relates to \'roof and home\' condition?', choices: ['Is your priority lowest monthly payment or ownership?', 'How old is the roof? Any leaks, shade issues, or upcoming renovations?', 'Are you hoping to move quickly or just exploring?', 'Would battery backup for key circuits be valuable?'], answerIndex: 1, explain: 'This question gathers roof age and condition details essential to site qualification and system design.' },
  { id: 'sol-070', category: 'Discovery', question: 'Which discovery question addresses \'financial priority\'?', choices: ['What\'s your daily commute like?', 'Do you have any pets?', 'Is your priority lowest monthly payment, ownership, or biggest long-term savings?', 'How many bedrooms does your home have?'], answerIndex: 2, explain: 'This question directly uncovers what the customer values most financially, shaping the financing recommendation.' },
  { id: 'sol-071', category: 'Discovery', question: 'Which discovery question addresses \'timing\'?', choices: ['Would battery backup for key circuits be valuable?', 'Are you hoping to move quickly or just exploring?', 'Are you interested in EV charging or efficiency upgrades?', 'What matters most to each decision maker?'], answerIndex: 1, explain: 'This question uncovers the customer\'s urgency and timeline, part of the \'timing\' discovery category.' },
  { id: 'sol-072', category: 'Discovery', question: 'Which discovery question addresses \'backup/resilience\'?', choices: ['How old is the roof?', 'Are you with National Grid or Eversource?', 'Do outages matter to you? Would battery backup for key circuits be valuable?', 'What\'s your total roof square footage?'], answerIndex: 2, explain: 'This question directly explores whether outage protection and battery backup matter to the customer.' },
  { id: 'sol-073', category: 'Discovery', question: 'What is the rep\'s core discovery goal, per the manual?', choices: ['Diagnose the customer\'s needs first; the best close is built from the customer\'s own answers', 'Pitch the proposal before asking any questions', 'Skip discovery entirely for door-to-door prospects', 'Ask only about the customer\'s income'], answerIndex: 0, explain: 'The manual explicitly states reps should not pitch before diagnosing, and that the best close comes from the customer’s own answers.' },
  { id: 'sol-074', category: 'Discovery', question: 'Which discovery question addresses the \'full energy roadmap\'?', choices: ['Do you prefer email or phone calls?', 'What\'s your favorite room in the house?', 'How long have you lived here?', 'Are you looking at solar only, or a broader energy plan including battery, EV charging, or efficiency upgrades?'], answerIndex: 3, explain: 'This question opens the conversation beyond solar alone to a broader home energy roadmap Nexis positions itself around.' },

  // ===== Sales Process (9) =====
  { id: 'sol-075', category: 'Sales Process', question: 'What is the first step in the 8-step solar sales process?', choices: ['Prospect', 'Qualify', 'Discover', 'Educate'], answerIndex: 0, explain: 'The process begins with Prospect — through doors, referrals, realtor/loan officer partners, or digital leads.' },
  { id: 'sol-076', category: 'Sales Process', question: 'Which step involves confirming homeowner status, the utility bill, roof/shade, and finance fit?', choices: ['Discover', 'Educate', 'Qualify', 'Close next step'], answerIndex: 2, explain: 'The Qualify step checks homeownership, the bill, roof/shade conditions, credit/finance fit, and decision-makers.' },
  { id: 'sol-077', category: 'Sales Process', question: 'Which step involves explaining the bill, solar, net metering, and system components in simple language?', choices: ['Handoff', 'Design review', 'Finance review', 'Educate'], answerIndex: 3, explain: 'The Educate step is where reps explain the bill, how solar works, net metering, and system components clearly.' },
  { id: 'sol-078', category: 'Sales Process', question: 'What happens during the \'Design review\' step?', choices: ['Comparing cash, loan, PPA/lease, and battery add-on options', 'Logging permit and inspection milestones', 'Showing the proposed layout, production estimate, offset assumptions, and options', 'Asking discovery questions about the customer\'s bill pain'], answerIndex: 2, explain: 'Design review is when the rep shows the proposed system layout, production estimate, offset assumptions, and options.' },
  { id: 'sol-079', category: 'Sales Process', question: 'What happens during the \'Finance review\' step?', choices: ['Comparing cash, loan, PPA/lease, and battery add-on if appropriate', 'Explaining how net metering works mechanically', 'Logging the outcome of the initial door knock', 'Setting permitting expectations for the customer'], answerIndex: 0, explain: 'Finance review is where financing options are compared based on the customer\'s stated priorities.' },
  { id: 'sol-080', category: 'Sales Process', question: 'What does the \'Handoff\' step set expectations around?', choices: ['Discovery questions to ask next', 'Permits, install, inspection, PTO, and ongoing support', 'The door-to-door prospecting area for the week', 'Objection handling scripts'], answerIndex: 1, explain: 'Handoff is the final step, setting realistic expectations for permitting, installation, inspection, PTO, and ongoing support.' },
  { id: 'sol-081', category: 'Sales Process', question: 'What best describes the \'Close next step\' stage?', choices: ['Explaining the difference between kW and kWh', 'Knocking on the next door in the neighborhood', 'Securing agreement, docs, site survey, interconnection, or a scheduled follow-up', 'Reviewing the customer\'s 12-month usage history'], answerIndex: 2, explain: 'Close next step is about securing whatever the appropriate next commitment is — not necessarily a fully signed sale immediately.' },
  { id: 'sol-082', category: 'Sales Process', question: 'Why does the manual instruct reps not to pitch before diagnosing?', choices: ['A strong proposal and close come from understanding the customer\'s actual priorities first', 'Pitching first always speeds up the sale', 'Diagnosis isn\'t necessary if the rep is experienced', 'Customers prefer being told what to buy immediately'], answerIndex: 0, explain: 'Skipping discovery risks a mismatched proposal; the best close ties back to what the customer said mattered to them.' },
  { id: 'sol-083', category: 'Sales Process', question: 'Which of these is NOT one of the 8 steps in the solar sales process?', choices: ['Prospect', 'Cold call script memorization', 'Qualify', 'Handoff'], answerIndex: 1, explain: 'The 8 steps are Prospect, Qualify, Discover, Educate, Design review, Finance review, Close next step, and Handoff — not script memorization.' },

  // ===== D2D (9) =====
  { id: 'sol-084', category: 'D2D', question: 'What should a rep consider before knocking, regarding target areas?', choices: ['Any home works regardless of ownership or roof condition', 'Only rental properties should be targeted', 'Owner-occupied homes, higher-usage neighborhoods, strong roof exposure, and visible comparable solar nearby', 'Neighborhoods with any existing solar installs should be avoided'], answerIndex: 2, explain: 'Good area selection focuses on owner-occupied homes with higher usage, strong roof exposure, and nearby comparable solar as social proof.' },
  { id: 'sol-085', category: 'D2D', question: 'What should a rep do if a home has a posted no-soliciting sign?', choices: ['Respect the sign and local rules', 'Knock anyway since solar reviews are different from typical sales', 'Argue that a solar review doesn\'t count as soliciting', 'Leave a flyer on the door regardless'], answerIndex: 0, explain: 'The manual instructs reps to respect no-soliciting signs and local rules, and to leave immediately if asked.' },
  { id: 'sol-086', category: 'D2D', question: 'What should a rep track after every single knock?', choices: ['Nothing — only successful appointments matter', 'Only the homeowner\'s phone number', 'The outcome (not home, renter, bad roof, interested, callback, appointment) with clean notes', 'The weather conditions that day'], answerIndex: 2, explain: 'Reps should log every knock outcome with clean notes to keep the pipeline accurate and support follow-up.' },
  { id: 'sol-087', category: 'D2D', question: 'Which is an example of the manual\'s 10-second opener?', choices: ['Sign this contract today or lose your solar eligibility.', 'Hi, I\'m [Name] with Nexis Power. We\'re in this area reviewing whether roofs qualify for Massachusetts solar programs... Do you own the home?', 'Your neighbor already signed, so you should too.', 'I guarantee your bill will be zero.'], answerIndex: 1, explain: 'This is the manual\'s example opener — short, respectful, and leads with a simple qualifying question.' },
  { id: 'sol-088', category: 'D2D', question: 'What is the goal at the door, per the manual\'s \'no-pressure posture\' guidance?', choices: ['A full signed sale on the first visit', 'Convincing the homeowner to skip reviewing their bill', 'Getting the homeowner\'s social security number', 'A qualified appointment with the right decision-makers and utility data'], answerIndex: 3, explain: 'The door goal is a qualified appointment, not a full sale — leaving respectfully whether the answer is yes or no.' },
  { id: 'sol-089', category: 'D2D', question: 'What should reps bring with them to support trust at the door?', choices: ['A generic script with no local relevance', 'Reviews, project photos, and financing talking points to build trust without overwhelming', 'Pressure tactics designed to close immediately', 'Guarantees about specific tax credit amounts'], answerIndex: 1, explain: 'Proof points like reviews and project photos should build trust in a light-touch way, without overwhelming the homeowner.' },
  { id: 'sol-090', category: 'D2D', question: 'What should a rep confirm when scheduling an appointment at the door?', choices: ['Homeowner name, best phone number, utility company, and appointment time, plus a reminder to have a recent bill ready', 'Only the homeowner\'s first name', 'The homeowner\'s exact household income', 'The homeowner\'s social media handles'], answerIndex: 0, explain: 'A proper appointment confirmation captures name, phone, utility, and time, plus a reminder to have the bill ready.' },
  { id: 'sol-091', category: 'D2D', question: 'What does the manual say about \'working the block\'?', choices: ['Share private customer details with neighbors to build urgency', 'Mention neighborhood trends generally without sharing private customer details, and finish one block with discipline before moving on', 'Skip any block with existing solar customers', 'Only work one house per full day'], answerIndex: 1, explain: 'Reps can reference general neighborhood trends but must not disclose private customer details, and should work a block fully before moving on.' },
  { id: 'sol-092', category: 'D2D', question: 'Which is a sound general D2D safety and legal practice, consistent with the manual’s compliance-first posture (industry-standard)?', choices: ['Carry visible ID/badge, respect local solicitation ordinances, and never enter a home without invitation', 'Enter a yard or home uninvited if a door happens to be unlocked', 'Argue with a homeowner who asks the rep to leave', 'Continue knocking after dark regardless of local curfew rules'], answerIndex: 0, explain: 'Standard D2D safety and legal practice includes visible identification, respecting local ordinances, and never entering a property without invitation.' },

  // ===== Objections (10) =====
  { id: 'sol-093', category: 'Objections', question: 'What does the L in the LAER framework stand for?', choices: ['Lead', 'Learn', 'Leverage', 'Listen'], answerIndex: 3, explain: 'LAER stands for Listen, Acknowledge, Explore, Respond — starting by letting the homeowner finish without interrupting.' },
  { id: 'sol-094', category: 'Objections', question: 'What is the purpose of the \'Acknowledge\' step in LAER?', choices: ['To show empathy and validate the customer\'s feelings without necessarily agreeing with a misconception', 'To agree with any misconception the customer holds', 'To immediately correct the customer', 'To end the conversation politely'], answerIndex: 0, explain: 'Acknowledge means showing calm, respectful empathy without necessarily agreeing with something inaccurate.' },
  { id: 'sol-095', category: 'Objections', question: 'What is the goal of the \'Explore\' step in LAER?', choices: ['To close the sale immediately', 'To ask a question that uncovers the real issue behind the objection (price, roof, timing, trust, or ownership)', 'To argue the customer out of their concern', 'To change the subject entirely'], answerIndex: 1, explain: 'Explore uses a targeted question to find the true concern behind the stated objection, since objections often mask a different root issue.' },
  { id: 'sol-096', category: 'Objections', question: 'What should the \'Respond\' step in LAER include?', choices: ['An overwhelming amount of technical detail', 'Pressure to sign immediately', 'A guarantee of exact savings', 'Facts, a clear analogy, or a next step, kept simple, ending with a question or transition'], answerIndex: 3, explain: 'Respond should be simple and clear, using facts or analogy, and should keep the conversation moving with a question or next step.' },
  { id: 'sol-097', category: 'Objections', question: 'For the objection \'Solar is too expensive,\' what is a good Explore-stage follow-up question?', choices: ['When you say expensive, do you mean the monthly payment or the total project cost?', 'Why don\'t you just trust me?', 'Do you want to lose this deal?', 'Are you sure you can even afford your current bill?'], answerIndex: 0, explain: 'This question digs into what \'expensive\' actually means to the customer — a monthly payment concern versus a total cost concern.' },
  { id: 'sol-098', category: 'Objections', question: 'What is a good rebuttal for \'I need to think about it\'?', choices: ['You need to decide right now or the offer disappears.', 'That\'s fine, I\'ll just leave you alone then.', 'Of course. What part do you want to think through — savings, equipment, contract, or timing?', 'Thinking about it usually just means no.'], answerIndex: 2, explain: 'This response respects the customer\'s need for time while helping isolate the specific area they want clarity on.' },
  { id: 'sol-099', category: 'Objections', question: 'What is the recommended rebuttal approach for \'I don\'t want a lien on my house\'?', choices: ['Explain that not every financing option works the same way, and offer to review options that avoid that structure', 'Dismiss the concern as irrelevant', 'Insist a lien is required for every solar installation', 'Refuse to discuss financing any further'], answerIndex: 0, explain: 'The manual\'s rebuttal acknowledges that financing structures differ and offers to review options addressing the specific concern.' },
  { id: 'sol-100', category: 'Objections', question: 'What is the core principle behind handling objections, per the manual\'s REP RULE?', choices: ['Debate to win the argument', 'Skip objections and move straight to close', 'Always assume the customer is wrong', 'Slow down, diagnose the concern, and respond with clarity — the goal is trust, not pressure'], answerIndex: 3, explain: 'The manual states reps should not debate to win; the goal is building trust through diagnosis and clarity, not pressuring the customer.' },
  { id: 'sol-101', category: 'Objections', question: 'What is a good rebuttal for \'My roof is too old\'?', choices: ['That doesn’t matter, we install on any roof regardless of condition.', 'That may be true, and if so we should find that out — roof condition is part of the qualification process.', 'Roof age never affects a solar installation.', 'You should replace your roof before ever talking to us.'], answerIndex: 1, explain: 'This response validates the concern honestly and ties it back to the qualification process rather than dismissing it.' },
  { id: 'sol-102', category: 'Objections', question: 'What is a good rebuttal for \'I heard solar is a scam\'?', choices: ['That’s a rude thing to say.', 'You should just trust me because I work here.', 'Solar scams don’t exist.', 'Bad companies create that impression — the safest approach is reviewing the bill, design, equipment, warranties, and contract terms before deciding.'], answerIndex: 3, explain: 'This rebuttal acknowledges the legitimate root of the concern (bad actors in the industry) and redirects to a transparent, verifiable review process.' },

  // ===== Compliance (10) =====
  { id: 'sol-103', category: 'Compliance', question: 'Which of these four statements is the compliant way to talk about a customer\'s future bill?', choices: ['You will never pay an electric bill again.', 'The goal is to reduce the electricity you purchase from the utility. Some fixed charges or uncovered usage may still remain.', 'This is basically free.', 'We guarantee exact savings and production.'], answerIndex: 1, explain: 'This is the manual\'s approved phrasing — it sets realistic expectations instead of promising a $0 bill or guaranteed savings.' },
  { id: 'sol-104', category: 'Compliance', question: 'Which of these four statements about incentives is compliant?', choices: ['The government pays for it.', 'Sign now or lose everything.', 'There may be incentives or tax credits if you qualify, but eligibility and program rules must be verified.', 'Incentives are guaranteed for every customer.'], answerIndex: 2, explain: 'This phrasing correctly conditions incentive eligibility on verification rather than promising automatic government payment.' },
  { id: 'sol-105', category: 'Compliance', question: 'Which of these four statements about outage backup is compliant?', choices: ['Solar alone typically shuts down during an outage. Backup power usually requires a properly designed battery storage system.', 'The battery will run your whole house.', 'Your system will work in an outage.', 'Backup is included with every solar installation.'], answerIndex: 0, explain: 'This is the accurate, non-misleading statement about outage backup requiring a properly designed battery system.' },
  { id: 'sol-106', category: 'Compliance', question: 'Which of these four statements about utility rates is compliant?', choices: ['Rates will definitely double.', 'Rates never change in Massachusetts.', 'Utility rates have historically increased, but future rates are not guaranteed. Solar can help reduce exposure to rising costs.', 'We guarantee your rate will never increase.'], answerIndex: 2, explain: 'This statement is factual about historical trends without making a speculative guarantee about future rate changes.' },
  { id: 'sol-107', category: 'Compliance', question: 'Which of these four statements avoids high-pressure sales tactics?', choices: ['Sign now or lose everything.', 'Some incentives, timelines, or utility conditions can change, so it\'s worth reviewing carefully, but the decision should still make sense for the homeowner.', 'You have to decide before I leave your house.', 'This offer disappears in the next five minutes.'], answerIndex: 1, explain: 'This phrasing avoids pressure tactics while still noting that timing considerations exist, keeping the process ethical.' },
  { id: 'sol-108', category: 'Compliance', question: 'Before presenting numbers, what must a rep verify about the customer profile?', choices: ['Customer name, service address, utility company/rate class, and homeowner/decision-maker status', 'Nothing — proposals can be built without confirming any details', 'Only the customer\'s phone number', 'Only the customer\'s email address'], answerIndex: 0, explain: 'Confirming customer profile basics ensures the proposal and utility interconnection are built on accurate information.' },
  { id: 'sol-109', category: 'Compliance', question: 'What is the GOLDEN RULE described in the Compliance module?', choices: ['Speed always beats accuracy', 'Always close on the very first visit', 'A clean sale is a sale the customer still understands after you leave — if they can\'t explain what they signed, slow down and re-teach', 'Never explain financing details to the customer'], answerIndex: 2, explain: 'The Golden Rule emphasizes customer understanding over speed — a clean sale requires the customer to genuinely understand what they signed.' },
  { id: 'sol-110', category: 'Compliance', question: 'What must a rep do regarding battery backup scope claims?', choices: ['Clarify whether the battery covers whole-home, critical loads, or no backup, avoiding overstated claims', 'Always claim the battery covers the whole home', 'Avoid mentioning battery scope at all', 'Assume every battery provides identical backup coverage'], answerIndex: 0, explain: 'Reps must clarify the actual battery backup scope (whole-home vs. critical loads vs. none) rather than overstating capability.' },
  { id: 'sol-111', category: 'Compliance', question: 'What must a rep do regarding system production and offset assumptions before presenting a design?', choices: ['State the numbers as guaranteed outcomes', 'Confirm the estimated system size, review the production estimate methodology, and explain that estimates are projections, not guarantees', 'Skip discussing offset assumptions entirely', 'Assume 100% offset for every customer regardless of usage'], answerIndex: 1, explain: 'System assumptions must be reviewed and explicitly framed as projections rather than guarantees.' },
  { id: 'sol-112', category: 'Compliance', question: 'Regarding timeline and interconnection, what must a rep set realistic expectations about?', choices: ['Nothing — timelines are always immediate', 'Only the installation date', 'Permitting, install, inspection, PTO, utility approval, and possible true-up/credit behavior', 'Only the financing approval date'], answerIndex: 2, explain: 'Reps must explain the interconnection path and set realistic expectations for permitting, install, inspection, PTO, and true-up/credit behavior.' },
];
window.SOLAR_EXAM_BANK = SOLAR_EXAM_BANK;
